/* FilterBar — inline filter dropdowns on desktop; a single "Filters" button
 * that opens a Modal sheet on mobile. */
.filter-bar {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

/* The "Filters" icon trigger (mobile) — count badge pinned to the corner. */
.filter-bar-trigger {
  position: relative;
  display: inline-flex;
}
.filter-bar-trigger .icon-button[data-active] { color: var(--primary-accent); }
/* The collapsed trigger reads as a CONTROL in the family of the search pill
 * beside it — white surface at rest — and commits on hover: primary fill,
 * glyph in white. A bare glyph on the muted header looked like decoration.
 * The border exists in BOTH states and every property rides one transition:
 * a border that pops in before the fill fades reads as a glitch, and a border
 * that appears only on hover shifts the glyph by a pixel. */
.filter-bar-trigger .icon-button {
  background: var(--card);
  border: var(--surface-edge);
  transition:
    background var(--duration-fast),
    border-color var(--duration-fast),
    color var(--duration-fast);
}
.filter-bar-trigger .icon-button:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--primary-foreground);
}
.filter-bar-count {
  position: absolute;
  inset-block-start: calc(-1 * var(--space-2xs));
  inset-inline-end: calc(-1 * var(--space-2xs));
  display: grid;
  place-items: center;
  min-width: var(--icon-sm);
  height: var(--icon-sm);
  padding: 0 var(--space-1);
  border-radius: var(--radius-full);
  background: var(--primary);
  /* A ring in the card colour: invisible on the resting white trigger, and the
   * thing that keeps the badge a separate object once the hovered trigger
   * fills primary — primary-on-primary was a number melting into its button. */
  box-shadow: 0 0 0 2px var(--card);
  color: var(--primary-foreground);
  font-size: var(--font-xs);
  font-weight: var(--font-weight-semibold);
  line-height: var(--leading-none);
  pointer-events: none;
}

/* Inside the modal — each filter rendered as a full-width select-style box. */
.filter-bar-sheet {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}
.filter-bar-sheet .filter-dropdown { display: block; }
.filter-bar-sheet .filter-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: var(--control-height);
  padding-inline: var(--control-padding-x);
  background: var(--background);
  /* --border-strong stays visible on the modal's --popover surface in dark
   * (regular --input == --popover there → border would vanish). */
  border: 1px solid var(--border-strong);
  border-radius: var(--control-radius);
  color: var(--foreground);
}
.filter-bar-sheet .filter-trigger:hover { border-color: var(--ring); }
.filter-bar-sheet .filter-trigger > .icon { margin-inline-start: auto; }

import './FilterBar.css'
import { useState, type ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { useMediaQuery } from '../lib/useMediaQuery'
import { FilterBarContext } from '../lib/filterBarContext'
import { Button } from '../Button'
import { IconButton } from '../IconButton'
import { Tooltip } from '../Tooltip'
import { Modal } from '../Modal'

type Props = {
  /** Filter dropdowns to show inline (desktop). */
  children: ReactNode
  /** Total active filter count across all filters — shows on mobile trigger. */
  activeCount: number
  /** Clears every filter. */
  onClear: () => void
  /** Always the icon + slide-out panel, at every width — for a screen that
   *  keeps its filters beside the search in the header row, where a row of
   *  chips has no room. The panel is the drawer Modal, sliding in from the
   *  inline end. Selections read per row: give each FilterDropdown `showTags`. */
  collapsed?: boolean
}

/* Below this width filters collapse into a "Filters" button + Modal sheet. */
const MOBILE_QUERY = '(max-width: 48rem)'

/**
 * The row of filters above a list: FilterDropdowns side by side on desktop,
 * one icon that opens them in a Modal sheet on mobile.
 */
export function FilterBar({ children, activeCount, onClear, collapsed }: Props) {
  const { t } = useTranslation()
  const isMobile = useMediaQuery(MOBILE_QUERY)
  const [open, setOpen] = useState(false)

  if (!collapsed && !isMobile) {
    return <div className="filter-bar">{children}</div>
  }

  return (
    <>
      <span className="filter-bar-trigger">
        <Tooltip content={t('filter.filters', { defaultValue: 'Filters' })}>
          <IconButton
            icon="tune"
            size="md"
            aria-label={t('filter.filters', { defaultValue: 'Filters' })}
            data-active={activeCount > 0 || undefined}
            onClick={() => setOpen(true)}
          />
        </Tooltip>
        {activeCount > 0 && <span className="filter-bar-count">{activeCount}</span>}
      </span>

      {/* A drawer, not a centred dialog: the panel slides in from the inline
        * end and the list stays visible behind it, so narrowing and watching
        * the result happen together. */}
      <Modal
        open={open}
        onClose={() => setOpen(false)}
        title={t('filter.filters', { defaultValue: 'Filters' })}
        placement="drawer"
        footer={
          /* No "Done": every filter applies the moment it is picked, so a
           * confirm button would only be a second Close. Clearing is the one
           * action that belongs down here. */
          <Button variant="secondary" onClick={onClear} disabled={activeCount === 0}>
            {t('filter.clearAll', { defaultValue: 'Clear all' })}
          </Button>
        }
      >
        <div className="filter-bar-sheet">
          <FilterBarContext value={{ inSheet: true }}>
            {children}
          </FilterBarContext>
        </div>
      </Modal>
    </>
  )
}
